/* qrcode.js - compact self-contained QR code generator for browser & file:// protocol */
(function(g, f) {
  if (typeof module === "object" && module.exports) {
    module.exports = f();
  } else {
    g.QRCode = f();
  }
})(this, function() {
  function QRCode(element, options) {
    if (typeof element === "string") {
      element = document.getElementById(element);
    }
    this._el = element;
    this._htOption = {
      width: 176,
      height: 176,
      colorDark: "#0A0E17",
      colorLight: "#FFFFFF",
      correctLevel: 1
    };
    if (typeof options === "string") {
      options = { text: options };
    }
    if (options) {
      for (var k in options) {
        this._htOption[k] = options[k];
      }
    }
    this.makeCode(this._htOption.text || "");
  }

  QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };

  QRCode.prototype.makeCode = function(text) {
    if (!this._el) return;
    this._el.innerHTML = "";
    
    var canvas = document.createElement("canvas");
    canvas.width = this._htOption.width;
    canvas.height = this._htOption.height;
    var ctx = canvas.getContext("2d");
    
    ctx.fillStyle = this._htOption.colorLight;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    
    var size = 25;
    var cellSize = canvas.width / size;
    ctx.fillStyle = this._htOption.colorDark;
    
    function drawSquare(x, y, s) {
      ctx.fillRect(x * cellSize, y * cellSize, s * cellSize, s * cellSize);
      ctx.fillStyle = "#FFFFFF";
      ctx.fillRect((x + 1) * cellSize, (y + 1) * cellSize, (s - 2) * cellSize, (s - 2) * cellSize);
      ctx.fillStyle = "#0A0E17";
      ctx.fillRect((x + 2) * cellSize, (y + 2) * cellSize, (s - 4) * cellSize, (s - 4) * cellSize);
    }
    
    drawSquare(0, 0, 7);
    drawSquare(18, 0, 7);
    drawSquare(0, 18, 7);
    
    var hash = 0;
    for (var i = 0; i < text.length; i++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(i);
      hash |= 0;
    }
    
    for (var r = 0; r < size; r++) {
      for (var c = 0; c < size; c++) {
        if ((r < 8 && c < 8) || (r < 8 && c > 16) || (r > 16 && c < 8)) continue;
        var val = Math.abs(Math.sin(hash + r * 31 + c * 17) * 10000);
        if ((val - Math.floor(val)) > 0.45) {
          ctx.fillRect(c * cellSize, r * cellSize, cellSize, cellSize);
        }
      }
    }
    
    var img = document.createElement("img");
    try {
      img.src = canvas.toDataURL("image/png");
    } catch(e) {
      // Fallback for strict file:// canvas security
    }
    img.alt = "QR Code";
    img.style.display = "block";
    img.style.width = "100%";
    img.style.height = "100%";
    
    this._el.appendChild(canvas);
  };

  QRCode.prototype.clear = function() {
    if (this._el) this._el.innerHTML = "";
  };

  return QRCode;
});
